import{_ as l,a0 as p,w as o,s as d,I as n,x as a,a1 as i,A as t,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"如何閲讀 Lynis 報告提高 Linux 安全性 | LCTT x X-CMD","titleTemplate":false,"description":"如何閲讀 Lynis 報告提高 Linux 安全性 | LCTT (202010) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何閲讀 Lynis 報告提高 Linux 安全性 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何閲讀 Lynis 報告提高 Linux 安全性 | LCTT (202010) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202010/20200810 How to read Lynis reports to improve Linux security","title":"如何閲讀 Lynis 報告提高 Linux 安全性","tag":"202010","desc":""},"relativePath":"202010/20200810 How to read Lynis reports to improve Linux security.md","filePath":"[post].md"}'),c={name:"202010/20200810 How to read Lynis reports to improve Linux security.md"};function h(u,s,g,b,k,y){const e=p("Link");return o(),d("div",null,[s[20]||(s[20]=n("h1",{id:"如何閲讀-lynis-報告提高-linux-安全性",tabindex:"-1"},[a("如何閲讀 Lynis 報告提高 Linux 安全性 "),n("a",{class:"header-anchor",href:"#如何閲讀-lynis-報告提高-linux-安全性","aria-label":"Permalink to “如何閲讀 Lynis 報告提高 Linux 安全性”"},"​")],-1)),s[21]||(s[21]=n("blockquote",null,[n("p",null,"使用 Lynis 的掃描和報告來發現和修復 Linux 安全問題。")],-1)),s[22]||(s[22]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202010/08/102355k7jakojhz9x8xamx.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("當我讀到 Gaurav Kamathe 的文章《",-1)),i(e,{href:"https://linux.cn/article-12696-1.html"},{default:t(()=>[...s[0]||(s[0]=[a("使用 Lynis 掃描 Linux 安全性",-1)])]),_:1}),s[2]||(s[2]=a("》時，讓我想起了我在美國勞工部擔任系統管理員的日子。我那時的職責之一是保證我們的 Unix 服務器的安全。每個季度，都會有一個獨立的核查員來審查我們服務器的安全狀態。每次在核查員預定到達的那一天，我都會運行 Security Readiness Review（SRR），這是一個掃描工具，它使用一大套腳本來識別和報告任何安全線索。SRR 是開源的，因此我可以查看所有源碼腳本及其功能。這使我能夠查看其代碼，確定具體是什麼問題，並迅速修復它發現的每個問題。",-1))]),s[23]||(s[23]=n("h3",{id:"什麼是-lynis",tabindex:"-1"},[a("什麼是 Lynis？ "),n("a",{class:"header-anchor",href:"#什麼是-lynis","aria-label":"Permalink to “什麼是 Lynis？”"},"​")],-1)),n("p",null,[i(e,{href:"https://github.com/CISOfy/lynis"},{default:t(()=>[...s[3]||(s[3]=[a("Lynis",-1)])]),_:1}),s[4]||(s[4]=a(" 是一個開源的安全審計工具，它的工作原理和 SRR 很像，它會掃描 Linux 系統，並提供它發現的任何弱點的詳細報告。同樣和 SRR 一樣，它也是由一大套腳本組成的，每個腳本都會檢查一個特定的項目，例如，最小和最大密碼時間要求。",-1))]),s[24]||(s[24]=r(`<p>運行 Lynis 後，你可以使用它的報告來定位每個項目的腳本，並瞭解 Lynis 是如何檢查和報告每個問題的。你也可以使用相同的腳本代碼來創建新的代碼來自動解決。</p><h3 id="如何閲讀-lynis-報告" tabindex="-1">如何閲讀 Lynis 報告 <a class="header-anchor" href="#如何閲讀-lynis-報告" aria-label="Permalink to “如何閲讀 Lynis 報告”">​</a></h3><p>由於 Gaurav 的文章介紹了 Lynis 的安裝和使用，在本文中，我將展示一些如何閲讀和使用其報告的例子。</p><p>請從運行一次審計開始：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lynis audit system --quick</span></span></code></pre></div><p>完成後，完整的報告將顯示在你的屏幕上。在底部，“Suggestions” 部分列出了所有可能需要修復以更好地加固系統的項目，以及每個項目的 TEST-ID。</p><p>要想加固系統並減少列表的大小，請開始解決每個項目。在 “Suggestions” 部分的描述可能包含了你需要採取的全部行動。如果沒有，你可以使用 <code>show details</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lynis show details TEST-ID</span></span></code></pre></div><p>例如，在我的系統中，有一條建議是：</p><blockquote><p>找不到 <code>locate</code> 所需的資料庫，運行 <code>updatedb</code> 或 <code>locate.updatedb</code> 來創建這個文件。[FILE-6410]</p></blockquote><p>看起來我只需要運行 <code>updatedb</code> 命令就行，但如果我想確定一下，我可以使用 Lynis 的 <code>show details</code> 選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lynis show details FILE-6410</span></span>
<span class="line"><span>2020-06-16 20:54:33 Performing test ID FILE-6410 (Checking Locate database)</span></span>
<span class="line"><span>2020-06-16 20:54:33 Test: Checking locate database</span></span>
<span class="line"><span>2020-06-16 20:54:33 Result: file /var/lib/mlocate/mlocate.db not found</span></span>
<span class="line"><span>2020-06-16 20:54:33 Result: file /var/lib/locate/locatedb not found</span></span>
<span class="line"><span>2020-06-16 20:54:33 Result: file /var/lib/locatedb not found</span></span>
<span class="line"><span>2020-06-16 20:54:33 Result: file /var/lib/slocate/slocate.db not found</span></span>
<span class="line"><span>2020-06-16 20:54:33 Result: file /var/cache/locate/locatedb not found</span></span>
<span class="line"><span>2020-06-16 20:54:33 Result: file /var/db/locate.database not found</span></span>
<span class="line"><span>2020-06-16 20:54:33 Result: database not found</span></span>
<span class="line"><span>2020-06-16 20:54:33 Suggestion: The database required for &#39;locate&#39; could not be found. Run &#39;updatedb&#39; or &#39;locate.updatedb&#39; to create this file. [test:FILE-6410] [details:-] [solution:-]</span></span>
<span class="line"><span>2020-06-16 20:54:33 ====</span></span></code></pre></div><p>這些細節表明 Lynis 無法找到各種文件。這個情況描述的非常清楚。我可以運行 <code>updatedb</code> 命令，然後重新檢查這個測試。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># updatedb</span></span>
<span class="line"><span># lynis --tests FILE-6410</span></span></code></pre></div><p>重新檢查細節時，會顯示它發現哪個文件滿足了測試：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lynis show details FILE-6410</span></span>
<span class="line"><span>2020-06-16 21:38:40 Performing test ID FILE-6410 (Checking Locate database)</span></span>
<span class="line"><span>2020-06-16 21:38:40 Test: Checking locate database</span></span>
<span class="line"><span>2020-06-16 21:38:40 Result: locate database found (/var/lib/mlocate/mlocate.db)</span></span>
<span class="line"><span>2020-06-16 21:38:40 Result: file /var/lib/locate/locatedb not found</span></span>
<span class="line"><span>2020-06-16 21:38:40 Result: file /var/lib/locatedb not found</span></span>
<span class="line"><span>2020-06-16 21:38:40 Result: file /var/lib/slocate/slocate.db not found</span></span>
<span class="line"><span>2020-06-16 21:38:40 Result: file /var/cache/locate/locatedb not found</span></span>
<span class="line"><span>2020-06-16 21:38:40 Result: file /var/db/locate.database not found</span></span>
<span class="line"><span>2020-06-16 21:38:40 ====</span></span></code></pre></div><h3 id="深入挖掘" tabindex="-1">深入挖掘 <a class="header-anchor" href="#深入挖掘" aria-label="Permalink to “深入挖掘”">​</a></h3><p>Lynis 的許多建議並不像這個建議那樣直接。如果你不確定某個發現或建議指的是什麼，就很難知道如何解決問題。假設你在一個新的 Linux 服務器上運行 Lynis，有幾項與 SSH 守護進程有關的內容，其中一項是關於 <code>MaxAuthTries</code> 的設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>* Consider hardening SSH configuration [SSH-7408]</span></span>
<span class="line"><span>    - Details  : MaxAuthTries (6 --&gt; 3)</span></span>
<span class="line"><span>      https://cisofy.com/lynis/controls/SSH-7408/</span></span></code></pre></div><p>要解決這個問題，你需要知道 SSH 配置文件的位置。一個經驗豐富的 Linux 管理員可能已經知道在哪裏找到它們，但如果你不知道，有一個方法可以看到 Lynis 在哪裏找到它們。</p><h4 id="定位-lynis-測試腳本" tabindex="-1">定位 Lynis 測試腳本 <a class="header-anchor" href="#定位-lynis-測試腳本" aria-label="Permalink to “定位 Lynis 測試腳本”">​</a></h4><p>Lynis 支持多種操作系統，因此你的安裝位置可能有所不同。在 Red Hat Enterprise Linux 或 Fedora Linux 系統中，使用 <code>rpm</code> 命令來查找測試文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># rpm -ql lynis</span></span></code></pre></div><p>這將列出所有測試文件，並報告它們在 <code>lynis/include</code> 目錄下的位置。在這個目錄下搜索你想知道的 TEST-ID（本例中為 SSH-7408）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grep SSH-7408 /usr/share/lynis/include/*</span></span>
<span class="line"><span>/usr/share/lynis/include/tests_ssh:    # Test        : SSH-7408</span></span></code></pre></div><h4 id="查找-ssh-問題" tabindex="-1">查找 SSH 問題 <a class="header-anchor" href="#查找-ssh-問題" aria-label="Permalink to “查找 SSH 問題”">​</a></h4><p>名為 <code>tests_ssh</code> 的文件中包含了 TEST-ID，在這裏可以找到與 SSH 相關的掃描函數。看看這個文件，就可以看到 Lynis 掃描器調用的各種函數。第一部分在一個名為 <code>SSH_DAEMON_CONFIG_LOCS</code> 的變量中定義了一個目錄列表。下面幾節負責檢查 SSH 守護進程的狀態、定位它的配置文件，並識別它的版本。我在 SSH-7404 測試中找到了查找配置文件的代碼，描述為 “確定 SSH 守護進程配置文件位置”。這段代碼包含一個 <code>for</code> 循環，在列表中的項目中搜索一個名為 <code>sshd_config</code> 的文件。我可以用這個邏輯來自己進行搜索：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find /etc /etc/ssh /usr/local/etc/ssh /opt/csw/etc/ssh -name sshd_config</span></span>
<span class="line"><span>/etc/ssh/sshd_config</span></span>
<span class="line"><span>/etc/ssh/sshd_config</span></span>
<span class="line"><span>find: ‘/usr/local/etc/ssh’: No such file or directory</span></span>
<span class="line"><span>find: ‘/opt/csw/etc/ssh’: No such file or directory</span></span></code></pre></div><p>進一步探索這個文件，就會看到尋找 SSH-7408 的相關代碼。這個測試涵蓋了 <code>MaxAuthTries</code> 和其他一些設置。現在我可以在 SSH 配置文件中找到該變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grep MaxAuthTries /etc/ssh/sshd_config</span></span>
<span class="line"><span>#MaxAuthTries 6</span></span></code></pre></div><h4 id="修復法律橫幅問題" tabindex="-1">修復法律橫幅問題 <a class="header-anchor" href="#修復法律橫幅問題" aria-label="Permalink to “修復法律橫幅問題”">​</a></h4><p>Lynis 還報告了一個與登錄系統時顯示的法律橫幅有關的發現。在我的家庭桌面系統上（我並不希望有很多其他人登錄），我沒有去改變默認的 <code>issue</code> 文件。企業或政府的系統很可能被要求包含一個法律橫幅，以警告用户他們的登錄和活動可能被記錄和監控。Lynis 用 BANN-7126 測試和 BANN-7130 測試報告了這一點：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>* Add a legal banner to /etc/issue, to warn unauthorized users [BANN-7126]</span></span>
<span class="line"><span>      https://cisofy.com/lynis/controls/BANN-7126/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>* Add legal banner to /etc/issue.net, to warn unauthorized users [BANN-7130]</span></span>
<span class="line"><span>      https://cisofy.com/lynis/controls/BANN-7130/</span></span></code></pre></div><p>我在運行 Fedora 32 工作站的系統上沒有發現什麼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /etc/issue /etc/issue.net</span></span>
<span class="line"><span>\\S</span></span>
<span class="line"><span>Kernel \\r on an \\m (\\l)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\S</span></span>
<span class="line"><span>Kernel \\r on an \\m (\\l)</span></span></code></pre></div><p>我可以添加一些諸如 “keep out” 或 “don&#39;t break anything” 之類的內容，但測試的描述並沒有提供足夠的信息來解決這個問題，所以我又看了看 Lynis 的腳本。我注意到 <code>include</code> 目錄下有一個叫 <code>tests_banners</code> 的文件；這似乎是一個很好的地方。在 <code>grep</code> 的幫助下，我看到了相關的測試：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grep -E &#39;BANN-7126|BANN-7130&#39; /usr/share/lynis/include/tests_banners</span></span>
<span class="line"><span>    # Test        : BANN-7126</span></span>
<span class="line"><span>    Register --test-no BANN-7126 --preqs-met \${PREQS_MET} --weight L --network NO --category security --description &quot;Check issue banner file contents&quot;</span></span>
<span class="line"><span>    # Test        : BANN-7130</span></span>
<span class="line"><span>    Register --test-no BANN-7130 --preqs-met \${PREQS_MET} --weight L --network NO --category security --description &quot;Check issue.net banner file contents&quot;</span></span></code></pre></div><p>在檢查了測試文件中的相關代碼後，我發現這兩個測試都是通過一個 <code>for</code> 循環來迭代一些預定義的法律術語：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for ITEM in \${LEGAL_BANNER_STRINGS}; do</span></span></code></pre></div><p>這些法律術語存儲在文件頂部定義的變量 <code>LEGAL_BANNER_STRINGS</code> 中。向後滾動到頂部可以看到完整的清單：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LEGAL_BANNER_STRINGS=&quot;audit access authori condition connect consent continu criminal enforce evidence forbidden intrusion law legal legislat log monitor owner penal policy policies privacy private prohibited record restricted secure subject system terms warning&quot;</span></span></code></pre></div><p>我最初的建議（“keep out” 或 “don&#39;t break anything”）不會滿足這個測試，因為它們不包含這個列表中的任何單詞。</p><p>下面這條橫幅信息包含了幾個必要的詞，因此，它將滿足這個測試，並防止 Lynis 報告它：</p><blockquote><p>Attention, by continuing to connect to this system, you consent to the owner storing a log of all activity. Unauthorized access is prohibited.</p></blockquote><p>請注意，這條信息必須被添加到 <code>/etc/issue</code> 和 <code>/etc/issue.net</code> 中。</p><h3 id="使其可重複" tabindex="-1">使其可重複 <a class="header-anchor" href="#使其可重複" aria-label="Permalink to “使其可重複”">​</a></h3><p>你可以手動進行這些編輯，但你可能要考慮自動化。例如，可能有許多設置需要更改，或者你可能需要在許多服務器上定期進行這些編輯。創建一個加固腳本將是簡化這個過程的好方法。對於 SSH 配置，在你的加固腳本中的一些 <code>sed</code> 命令可以解決這些發現。或者，你可以使用 <code>echo</code> 語句來添加合法的橫幅。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -i &#39;/MaxAuthTries/s/#MaxAuthTries 6/MaxAuthTries 3/&#39; /etc/ssh/sshd_config</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;Legal Banner&quot; | tee -a /etc/issue /etc/issue.net</span></span></code></pre></div><p>自動化使你能夠創建一個可重複的腳本，可以在你的基礎設施中保存和管理。你也可以在你的初始服務器配置中加入這個腳本。</p><h3 id="加固你的系統" tabindex="-1">加固你的系統 <a class="header-anchor" href="#加固你的系統" aria-label="Permalink to “加固你的系統”">​</a></h3><p>這種類型的練習可以提高你的腳本技能，既可以跟着現有的代碼走，也可以寫自己的腳本。因為 Lynis 是開源的，所以你可以很容易地看到你的系統是如何被檢查的，以及它的報告意味着什麼。最終的結果將是一個完善的系統，你可以在審計人員來的時候隨時向他們炫耀。</p><hr>`,52)),n("p",null,[s[6]||(s[6]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/20/8/linux-lynis-security"},{default:t(()=>[...s[5]||(s[5]=[a("https://opensource.com/article/20/8/linux-lynis-security",-1)])]),_:1})]),n("p",null,[s[11]||(s[11]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/alanfdoss"},{default:t(()=>[...s[7]||(s[7]=[a("Alan Formy-Duval",-1)])]),_:1}),s[12]||(s[12]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[8]||(s[8]=[a("lujun9972",-1)])]),_:1}),s[13]||(s[13]=a(" 譯者：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1}),s[14]||(s[14]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[17]||(s[17]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[a("Linux中國",-1)])]),_:1}),s[19]||(s[19]=a(" 榮譽推出",-1))])])}const x=l(c,[["render",h]]);export{L as __pageData,x as default};
